        {approvedProtocols.error && <ErrorAlert message={approvedProtocols.error} />}
        {isLoadingGroups && <LoadingState label="Loading groups..." />}
        {groupError && <ErrorAlert message={groupError} />}

        <ExperimentGroupTable groups={groups} />
